// Filter: return only first pending_kie row
const rows = $input.all().map(i => i.json);
const pending = rows.filter(r => r.action === 'pending_kie');
if (pending.length === 0) return [];
// Process one at a time (checker runs every 10 min, handles 1 per cycle)
return [{json: pending[0]}];

// Parse stored context from logs sheet (action=pending_kie)
const row = $input.first().json;
// Context JSON is stored in notes column
let ctx = {};
try { ctx = JSON.parse(row.notes || '{}'); } catch(e) {}
return [{json: {
  ...ctx,
  _task_id: row.job_id,          // KIE task_id stored in job_id column
  _row_created_at: row.timestamp, // creation time stored in timestamp
  _pending_row: row
}}];

// Shim: provides Smart Classifier interface from stored context
const d = $('Parse Context').first().json;
return [{json: {
  job_id: d.job_id || '',
  idea_id: d.idea_id || '',
  category: d.category || '',
  publish_slot: d.publish_slot || '',
  yt_category_id: d.yt_category_id || '22',
  category_label: d.category_label || '',
  final_topic: d.final_topic || '',
  hook_style: d.hook_style || '',
  kling_prompt_hint: d.kling_prompt_hint || ''
}}];

// KIE Status Check — Checker Workflow
// Called once per 10-min cycle, routes to success/failure/still-pending
const input = $input.first().json;
const ctx = $('Parse Context').first().json;

const createdAt = new Date(ctx._row_created_at || new Date());
const ageMinutes = (Date.now() - createdAt) / 60000;
const TIMEOUT_MINUTES = 40;

const data = input.data || {};
const state = data.successFlag ?? data.state ?? data.status ?? 'pending';

const isSuccess =
  state === 1 || state === '1' ||
  String(state).toLowerCase() === 'success' ||
  String(state).toLowerCase() === 'succeed' ||
  String(state).toLowerCase() === 'completed';

const isFailed =
  state === 2 || state === 3 || state === '2' || state === '3' ||
  String(state).toLowerCase() === 'failed' ||
  String(state).toLowerCase() === 'fail' ||
  String(state).toLowerCase() === 'error' ||
  String(state).toLowerCase() === 'timeout';

const isTimeout = ageMinutes > TIMEOUT_MINUTES;

const is_success = isSuccess;
const is_failed = !isSuccess && (isFailed || isTimeout); // success always wins

const status_reason = is_failed
  ? (data.failMsg || data.msg || data.fail_reason ||
     (isTimeout ? `KIE timeout after ${Math.round(ageMinutes)} min` : 'KIE generation failed'))
  : '';

return [{json: {
  ...input,
  is_success,
  is_failed,
  is_generating: !is_success && !is_failed,
  status_reason,
  _poll_count: 1,
  elapsed_seconds: Math.round(ageMinutes * 60),
  data,
  job_id: ctx.job_id || '',
  category: ctx.category || '',
  youtube_title: ctx.youtube_title || ctx.final_topic || '',
  topic: ctx.final_topic || '',
  quality_score: ctx.quality_score || 0
}}];

// ============================================================
// NODE: Extract Video URL — Wan 2.2 Speech-to-Video
// يستخرج رابط الفيديو النهائي من ناتج KIE
// ============================================================

const raw = $input.first().json;

// 1. فحص الفشل أولاً
if (raw.is_failed) {
  throw new Error(`Video generation failed after ${raw.elapsed_seconds}s. Reason: ${raw.status_reason}`);
}

const data = raw.data || raw;

// 2. محاولة قراءة resultJson (قد يكون string أو object)
let resultJson = data.resultJson || data;
if (typeof resultJson === 'string') {
  try { resultJson = JSON.parse(resultJson); } catch (e) {}
}

// 3. البحث عن رابط الفيديو في كل المواقع الممكنة
const candidates = [
  // المسار الأكثر شيوعاً لـ KIE
    resultJson?.data?.resultUrls,
  resultJson?.resultUrls,
  data?.resultUrls,
  resultJson?.data?.result_urls,
  resultJson?.result_urls,
  data?.result_urls,
  // مسارات بديلة
  [resultJson?.data?.video_url],
  [resultJson?.video_url],
  [data?.videoUrl],
  [data?.video_url],
  [data?.url],
  // مسار Wan الخاص
  resultJson?.data?.output?.video_url,
  resultJson?.output?.video_url,
  // مسار array مسطح
  resultJson?.data?.urls,
  resultJson?.urls
];

let videoUrl = null;

for (const candidate of candidates) {
  if (!candidate) continue;

  // إذا كان array
  if (Array.isArray(candidate) && candidate.length > 0) {
    const url = String(candidate[0]).trim();
    if (url.startsWith('http')) {
      videoUrl = url;
      break;
    }
  }

  // إذا كان string مباشر
  if (typeof candidate === 'string' && candidate.startsWith('http')) {
    videoUrl = candidate.trim();
    break;
  }
}

// 4. إذا لم نجد رابطاً، نرمي خطأ مع تفاصيل للاستكشاف
if (!videoUrl) {
  const debugInfo = JSON.stringify({
    data_keys: Object.keys(data),
    resultJson_keys: typeof resultJson === 'object' ? Object.keys(resultJson) : 'not_object',
    successFlag: data.successFlag,
    state: data.state
  }).slice(0, 800);

  throw new Error(`No video URL found in KIE response. Debug: ${debugInfo}`);
}

// 5. جمع البيانات من العقد السابقة
const parseData = $('Parse Gemini Output').first().json;
const classData = $('Smart Classifier').first().json;
const taskId = $('Parse Context').first().json._task_id || '';

return [{
  json: {
    ...parseData,
    ...classData,
    video_url: videoUrl,
    kie_task_id: taskId,
    video_ready_at: new Date().toISOString(),
    render_model: 'wan-2-2-speech-to-video',
    total_generation_seconds: raw.elapsed_seconds || 0,
    poll_count: raw._poll_count || 0
  }
}];

// ============================================================
// NODE: Pre-Publish Builder — Wan Speech-to-Video
// ============================================================

const parseData = $('Parse Gemini Output').first().json;
const classData = $('Smart Classifier').first().json;
const videoBinary = $('Download Video').first().binary;

if (!videoBinary?.video_data) {
  throw new Error('Final video binary not found. Expected: Download Video → video_data');
}

const data = {
  ...parseData,
  yt_category_id: parseData.yt_category_id || classData.yt_category_id || '22',
  category_label: parseData.category_label || classData.category_label || '',
  job_id: parseData.job_id || classData.job_id || '',
  final_topic: parseData.final_topic || classData.final_topic || '',
  quality_score: parseData.quality_score || 0,
};

// Title
let title = String(
  parseData.youtube_title ||
  data.final_topic ||
  'حين يصمت القلب تتكلم الروح'
).trim();

title = title
  .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
  .trim();

if ([...title].length > 80) {
  title = [...title].slice(0, 77).join('').trim() + '...';
}

// Hashtags
let finalTags = Array.isArray(parseData.hashtags)
  ? parseData.hashtags
  : String(parseData.hashtags || '').split(/\s+/);

finalTags = finalTags
  .map(tag => String(tag)
    .trim()
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
    .trim()
  )
  .filter(Boolean)
  .map(tag => tag.startsWith('#') ? tag : '#' + tag)
  .filter(tag => /^#[\w\u0600-\u06FF]+$/.test(tag));

finalTags = [...new Set(finalTags)].slice(0, 12);

const cleanTags = finalTags.map(tag => tag.replace('#', ''));
const hashBlock = finalTags.join(' ');

// Description
let baseDesc = String(parseData.youtube_description || '').trim();

baseDesc = baseDesc
  .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
  .trim();

const finalDescription = [
  baseDesc,
  '',
  hashBlock,
  '',
  'اشترك للمزيد من الفيديوهات الإسلامية الفكرية والتأملية.',
  'محتوى مرئي بالذكاء الاصطناعي لأغراض التدبر والتفكر.'
].join('\n');

// Scheduling
const TIMEZONE_OFFSET_HOURS = 3;

const now = new Date();
const localNow = new Date(
  now.getTime() + TIMEZONE_OFFSET_HOURS * 60 * 60 * 1000
);

const publishAt = new Date(localNow);
publishAt.setUTCHours(21, 0, 0, 0);

if (publishAt <= localNow) {
  publishAt.setUTCDate(publishAt.getUTCDate() + 1);
}

const publishAtUtc = new Date(
  publishAt.getTime() - TIMEZONE_OFFSET_HOURS * 60 * 60 * 1000
);

// Voiceover statistics
const voiceover = String(parseData.voiceover_arabic || '');
const voiceWords = voiceover.split(/\s+/).filter(Boolean).length;

return [{
  json: {
    ...data,
    final_title: title,
    final_description: finalDescription,
    final_tags: finalTags,
    clean_tags: cleanTags,
    scheduled_publish_at: publishAtUtc.toISOString(),

    qa_summary: {
      title_chars: [...title].length,
      hashtags_count: finalTags.length,
      quality_score: parseData.quality_score,
      category: data.category_label || parseData.category,
      render_model: 'wan/2-2-a14b-speech-to-video-turbo',
      production_mode: 'speech_to_video',
      audio_source: 'elevenlabs/text-to-dialogue-v3',
      voiceover_words: voiceWords,
      voiceover_ok: voiceWords >= 28 && voiceWords <= 48,
      video_synced: true
    }
  },

  binary: videoBinary
}];

