const blockedStatuses = new Set([
  'completed',
  'in_progress',
  'rejected',
  'failed',
  'skipped'
]);

function text(value) {
  return String(value || '').trim();
}

function isReadyIdea(row) {
  const status = text(row.production_status).toLowerCase();

  return (
    text(row.idea).length > 20 &&
    !blockedStatuses.has(status)
  );
}

// تحديد ترتيب فئة اليوم
let currentIndex = Number(classifier.category_rotation_index);

if (!Number.isInteger(currentIndex) || currentIndex < 0) {
  currentIndex = CATEGORIES.findIndex(item => item.id === classifier.category);
}

if (currentIndex < 0) currentIndex = 0;

// نأخذ فئات الأيام الثلاثة القادمة فقط
const nextThreeCategories = [1, 2, 3].map(offset => {
  return CATEGORIES[(currentIndex + offset) % CATEGORIES.length];
});

// الأفكار الجاهزة الموجودة فعليًا لكل فئة من الفئات القادمة
const futureStats = nextThreeCategories.map(category => {
  const allCategoryIdeas = sheetRows.filter(row => {
    return text(row.category) === category.id;
  });

  const readyIdeas = allCategoryIdeas.filter(isReadyIdea);

  return {
    id: category.id,
    label: category.label,
    readyCount: readyIdeas.length,
    totalHistoryCount: allCategoryIdeas.filter(row => text(row.idea)).length,
    angles: category.angles
  };
});

