    .filter(row => text(row.category) === plan.id && text(row.idea))
    .slice(-8)
    .map((row, index) => {
      return `${index + 1}. ${text(row.idea).slice(0, 350)}`;
    });

  return [
    `CATEGORY: ${plan.id} — ${plan.label}`,
    ideas.length ? ideas.join('\n') : 'No previous ideas stored for this category.'
  ].join('\n');
}).join('\n\n---\n\n').slice(0, 6500);

const categoryPlanText = categoryPlan.map(plan => {
