  throw new Error('Invalid category plan. Expected exactly 3 categories.');
}

// جميع الأفكار السابقة، مرتبة حسب الفئة
const previousByCategory = {};

for (const row of sheetRows) {
  const category = cleanText(row.category);
  const idea = cleanText(row.idea);

  if (!category || !idea) continue;

  if (!previousByCategory[category]) {
    previousByCategory[category] = [];
  }

  previousByCategory[category].push(idea);
}

// نستخدم كل الأفكار السابقة لمنع التكرار
const acceptedIdeasByCategory = {};

const output = [];
const timestamp = Date.now();

for (let index = 0; index < categoryPlan.length; index++) {
  const plan = categoryPlan[index];

  // نبحث عن العنصر المطابق للفئة المطلوبة
  const candidate = generatedIdeas.find(item => {
    return cleanText(item.category) === plan.id;
  });

  if (!candidate) {
    continue;
  }

  const idea = cleanText(candidate.idea);
  const visualPrompt = cleanText(candidate.kling_prompt);
  const angle = cleanText(candidate.angle);

  // تحقق من جودة الفكرة
  if (!isValidArabicIdea(idea)) {
    continue;
  }

  // تحقق من جودة Visual Prompt
  if (!isValidPrompt(visualPrompt)) {
    continue;
  }

  const oldIdeas = previousByCategory[plan.id] || [];
  const acceptedInSameCategory = acceptedIdeasByCategory[plan.id] || [];

  const duplicatedWithOld = oldIdeas.some(oldIdea => {
    return isTooSimilar(idea, oldIdea);
  });

  const duplicatedInBatch = acceptedInSameCategory.some(newIdea => {
    return isTooSimilar(idea, newIdea);
  });

  // لا نضيف الفكرة إن كانت متكررة أو قريبة جدًا
  if (duplicatedWithOld || duplicatedInBatch) {
    continue;
  }

  if (!acceptedIdeasByCategory[plan.id]) {
    acceptedIdeasByCategory[plan.id] = [];
  }

  acceptedIdeasByCategory[plan.id].push(idea);

  let priority = cleanText(candidate.priority).toLowerCase();

  if (!['high', 'medium'].includes(priority)) {
    priority = 'medium';
  }

  output.push({
    json: {
      id: `auto_rolling_${timestamp}_${index + 1}`,

      idea,
      category: plan.id,

      production_status: 'pending',
      priority,

      // الفكرة الأولى تحتاج غالبًا غدًا، الثانية بعد غد، الثالثة بعده
      scheduled_date: getFutureDate(index + 1),
      scheduled_time: '21:00',

      // اسم العمود يبقى kling_prompt لتوافق الشيت والكود القديم
      kling_prompt: visualPrompt,

      youtube_title: '',
      hashtags: '',

      notes: [
        'auto-generated rolling idea bank',
        `angle=${angle || plan.required_angle || 'not_specified'}`,
        `category=${plan.id}`,
        `parseError=${parseError || 'none'}`
      ].join(' | ')
    }
  });
}

