        ready_ideas: item.readyCount
      })),
      covered_future_categories: coveredFutureCategories
    }
  }
}];

// ============================================================
// Parse New Ideas
// يتحقق من 3 أفكار إسلامية قبل حفظها في شيت ideas
// ============================================================

const aiResponse = $input.first().json;
const brief = $('Build Rolling Idea Bank Brief').first().json;
const sheetRows = $('Get Ideas (ideas sheet)').all().map(item => item.json || {});

// استخراج الرد من Agent
let raw =
  aiResponse.output ??
  aiResponse.text ??
  aiResponse.message?.content ??
  aiResponse.choices?.[0]?.message?.content ??
  '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

let clean = raw
  .replace(/^\uFEFF/, '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/[\u201C\u201D]/g, '"')
  .trim();

let generatedIdeas = [];
let parseError = '';

try {
  const match = clean.match(/\[[\s\S]*\]/);

  if (!match) {
    throw new Error('No JSON array found in AI response');
  }

  generatedIdeas = JSON.parse(match[0]);

  if (!Array.isArray(generatedIdeas)) {
    throw new Error('Response is not an array');
  }
} catch (error) {
  parseError = String(error.message || error);
  generatedIdeas = [];
}

// تنظيف النص العربي للمقارنة
function normalizeArabic(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670]/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/[^\u0600-\u06FFa-z0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const STOP_WORDS = new Set([
  'في', 'من', 'الى', 'إلى', 'عن', 'على', 'مع', 'هذا', 'هذه',
  'ذلك', 'تلك', 'التي', 'الذي', 'أن', 'ان', 'لا', 'ما', 'ثم',
  'قد', 'كان', 'تكون', 'ليس', 'كل', 'حين', 'عند', 'بعد', 'قبل',
  'هو', 'هي', 'كما', 'لكن', 'لعل', 'بين', 'حتى', 'أو', 'و'
]);

function meaningfulTokens(value) {
  return [...new Set(
    normalizeArabic(value)
      .split(/\s+/)
      .filter(token => token.length >= 3)
      .filter(token => !STOP_WORDS.has(token))
  )];
}

function similarityScore(a, b) {
  const tokensA = meaningfulTokens(a);
  const tokensB = meaningfulTokens(b);

  if (!tokensA.length || !tokensB.length) return 0;

  const setA = new Set(tokensA);
  const setB = new Set(tokensB);

  let intersection = 0;

  for (const token of setA) {
    if (setB.has(token)) intersection++;
  }

  const union = new Set([...setA, ...setB]).size;

  return union ? intersection / union : 0;
}

function isTooSimilar(candidate, previous) {
  const candidateNormalized = normalizeArabic(candidate);
  const previousNormalized = normalizeArabic(previous);

  if (!candidateNormalized || !previousNormalized) return false;

  if (candidateNormalized === previousNormalized) return true;

  const score = similarityScore(candidate, previous);

  return score >= 0.62;
}

function cleanText(value) {
  return String(value || '')
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27FF}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isValidArabicIdea(value) {
  const text = cleanText(value);

  return (
    text.length >= 100 &&
    /[\u0600-\u06FF]/.test(text)
  );
}

function isValidPrompt(value) {
  const text = cleanText(value);

  const forbidden = /cctv|rescue|accident|gore|blood|violence|weapon|crime|crowd/i;

  return (
    text.length >= 120 &&
    !/[\u0600-\u06FF]/.test(text) &&
    !forbidden.test(text) &&
    /9:16/i.test(text) &&
    /veiled|hijab/i.test(text) &&
    /lips/i.test(text)
  );
}

function getFutureDate(daysAhead) {
  const date = new Date();
  date.setUTCDate(date.getUTCDate() + daysAhead);
  return date.toISOString().slice(0, 10);
}

// الخطة التي حددتها عقدة Build Rolling Idea Bank Brief
const categoryPlan = Array.isArray(brief.category_plan)
  ? brief.category_plan
  : [];

if (categoryPlan.length !== 3) {
  throw new Error('Invalid category plan. Expected exactly 3 categories.');
}

// جميع الأفكار السابقة، مرتبة حسب الفئة
const previousByCategory = {};

for (const row of sheetRows) {
  const category = cleanText(row.category);
  const idea = cleanText(row.idea);

  if (!category || !idea) continue;

  if (!previousByCategory[category]) {
    previousByCategory[category] = [];
  }

  previousByCategory[category].push(idea);
}

// نستخدم كل الأفكار السابقة لمنع التكرار
const acceptedIdeasByCategory = {};

const output = [];
const timestamp = Date.now();

for (let index = 0; index < categoryPlan.length; index++) {
  const plan = categoryPlan[index];

  // نبحث عن العنصر المطابق للفئة المطلوبة
  const candidate = generatedIdeas.find(item => {
    return cleanText(item.category) === plan.id;
  });

  if (!candidate) {
    continue;
  }

  const idea = cleanText(candidate.idea);
  const visualPrompt = cleanText(candidate.kling_prompt);
  const angle = cleanText(candidate.angle);

  // تحقق من جودة الفكرة
  if (!isValidArabicIdea(idea)) {
    continue;
  }

  // تحقق من جودة Visual Prompt
  if (!isValidPrompt(visualPrompt)) {
    continue;
  }

  const oldIdeas = previousByCategory[plan.id] || [];
  const acceptedInSameCategory = acceptedIdeasByCategory[plan.id] || [];

  const duplicatedWithOld = oldIdeas.some(oldIdea => {
    return isTooSimilar(idea, oldIdea);
  });

  const duplicatedInBatch = acceptedInSameCategory.some(newIdea => {
    return isTooSimilar(idea, newIdea);
  });

  // لا نضيف الفكرة إن كانت متكررة أو قريبة جدًا
  if (duplicatedWithOld || duplicatedInBatch) {
    continue;
  }

  if (!acceptedIdeasByCategory[plan.id]) {
    acceptedIdeasByCategory[plan.id] = [];
  }

  acceptedIdeasByCategory[plan.id].push(idea);

  let priority = cleanText(candidate.priority).toLowerCase();

  if (!['high', 'medium'].includes(priority)) {
    priority = 'medium';
  }

  output.push({
    json: {
      id: `auto_rolling_${timestamp}_${index + 1}`,

      idea,
      category: plan.id,

      production_status: 'pending',
      priority,

      // الفكرة الأولى تحتاج غالبًا غدًا، الثانية بعد غد، الثالثة بعده
      scheduled_date: getFutureDate(index + 1),
      scheduled_time: '21:00',

      // اسم العمود يبقى kling_prompt لتوافق الشيت والكود القديم
      kling_prompt: visualPrompt,

      youtube_title: '',
      hashtags: '',

      notes: [
        'auto-generated rolling idea bank',
        `angle=${angle || plan.required_angle || 'not_specified'}`,
        `category=${plan.id}`,
        `parseError=${parseError || 'none'}`
      ].join(' | ')
    }
  });
}

return output;
